"""Exact attribution normalization for already-tolerant approval and refresh protocols.

Merge authorization deliberately rejects attribution; do not use this helper there.
Workflow Scheduler keeps its independent, standalone parser.
"""

_CLAUDE_CODE_ATTRIBUTION_FOOTER = "\n\n---\n_Generated by [Claude Code](https://claude.ai/code)_"
_CLAUDE_CODE_FOOTERS = (
    _CLAUDE_CODE_ATTRIBUTION_FOOTER,
    "\n\n---\n_Generated by [Claude Code](https://claude.ai)_",
)


def strip_one_known_footer(body: str) -> str:
    """Strip only one known trailing footer, leaving other bodies unchanged."""
    for footer in _CLAUDE_CODE_FOOTERS:
        if body.endswith(footer):
            candidate = body[: -len(footer)]
            if not any(known in candidate for known in _CLAUDE_CODE_FOOTERS):
                return candidate
    return body
